[CmdletBinding()]
param([switch]$RequirePassed,[string]$EvidenceFile=(Join-Path $PSScriptRoot '..\docs\finance\staging-recovery-evidence.json'))
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$d=Get-Content -Raw -LiteralPath (Resolve-Path $EvidenceFile)|ConvertFrom-Json -Depth 30
if($d.schemaVersion -ne 1 -or $d.module -ne 'OTOTR_FRANCHISE_FINANCE' -or $d.target -ne 'PREPRODUCTION_RECOVERY'){throw 'Invalid finance recovery evidence identity.'}
if($d.productionDataUsed -or $d.preProductionDecision -ne 'NO_GO' -or $d.status -notin @('NOT_RUN','RUNNING','FAILED','PASSED')){throw 'Finance recovery evidence policy is invalid.'}
$names=@('Yedek oluşturma ve hash','Ayrı hedefe restore','Katalog ve finansal bütünlük','Yazma erişimini kapatma','Uygulama rollback','Geriye uyumlu forward-fix');if(@($d.drills).Count -ne 6){throw 'Expected six finance recovery drills.'}
for($i=0;$i -lt 6;$i++){$drill=$d.drills[$i];$id='REC-FIN-{0:d2}' -f ($i+1);if($drill.id -ne $id -or $drill.name -ne $names[$i] -or $drill.status -notin @('NOT_RUN','RUNNING','FAILED','PASSED')){throw "Invalid recovery drill: $($drill.id)"};if($drill.status -eq 'PASSED'){if(-not $drill.evidence -or @($drill.evidence).Count -lt 1){throw "Recovery evidence missing: $id"};foreach($item in $drill.evidence){if([string]::IsNullOrWhiteSpace($item.path) -or $item.path -match '^[A-Za-z]:|^\\|^/'){throw "Recovery evidence path must be repository-relative: $id"};$path=[IO.Path]::GetFullPath((Join-Path $root $item.path));if(-not $path.StartsWith($root,[StringComparison]::OrdinalIgnoreCase) -or -not (Test-Path $path -PathType Leaf) -or (Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $item.sha256){throw "Recovery evidence invalid: $id"}}}}
if($d.status -eq 'PASSED'){
 foreach($name in @('environmentId','deployedCommit','startedAtUtc','completedAtUtc','executedByIdentitySha256','approvedByIdentitySha256')){if([string]::IsNullOrWhiteSpace($d.run.$name)){throw "Passed recovery metadata missing: $name"}}
 if($d.run.deployedCommit -notmatch '^[a-f0-9]{40}$' -or $d.run.executedByIdentitySha256 -notmatch '^[a-f0-9]{64}$' -or $d.run.approvedByIdentitySha256 -notmatch '^[a-f0-9]{64}$' -or $d.run.executedByIdentitySha256 -eq $d.run.approvedByIdentitySha256){throw 'Recovery commit or maker-checker identity is invalid.'}
 if(@($d.drills|Where-Object status -ne 'PASSED').Count -gt 0){throw 'All recovery drills must pass.'}
 foreach($name in @('approvedRtoMinutes','approvedRpoMinutes','observedRecoveryMinutes','observedDataLossMinutes')){if($null -eq $d.objectives.$name -or [decimal]$d.objectives.$name -lt 0){throw "Recovery objective missing: $name"}}
 if([decimal]$d.objectives.approvedRtoMinutes -le 0 -or [decimal]$d.objectives.observedRecoveryMinutes -gt [decimal]$d.objectives.approvedRtoMinutes -or [decimal]$d.objectives.observedDataLossMinutes -gt [decimal]$d.objectives.approvedRpoMinutes){throw 'Recovery RTO or RPO target breached.'}
 $approval=[IO.Path]::GetFullPath((Join-Path $root $d.objectives.approvalEvidencePath));if(-not $approval.StartsWith($root,[StringComparison]::OrdinalIgnoreCase) -or -not (Test-Path $approval -PathType Leaf) -or (Get-FileHash $approval -Algorithm SHA256).Hash.ToLowerInvariant() -ne $d.objectives.approvalEvidenceSha256){throw 'Recovery objective approval evidence is invalid.'}
 if($d.restore.separateTarget -ne $true -or $d.restore.sourceOverwritten -ne $false -or $d.restore.destructiveDownMigrationUsed -ne $false -or $d.restore.writeAccessDisabledDuringDrill -ne $true){throw 'Unsafe recovery behavior detected.'}
 foreach($name in @('backupSha256','sourceControlSha256','restoredControlSha256')){if($d.restore.$name -notmatch '^[a-f0-9]{64}$'){throw "Recovery hash missing: $name"}}
 if($d.restore.sourceControlSha256 -ne $d.restore.restoredControlSha256){throw 'Restored financial control hash mismatch.'}
 foreach($pair in @(@('expectedFinanceTables','restoredFinanceTables'),@('expectedFinanceApiFunctions','restoredFinanceApiFunctions'))){if([int]$d.restore.($pair[0]) -le 0 -or [int]$d.restore.($pair[0]) -ne [int]$d.restore.($pair[1])){throw "Restored catalog mismatch: $($pair[0])"}}
 if($d.restore.rollbackCommit -notmatch '^[a-f0-9]{40}$' -or $d.restore.forwardFixCommit -notmatch '^[a-f0-9]{40}$'){throw 'Rollback and forward-fix commits are required.'}
}
Write-Host "FINANCE STAGING RECOVERY: $($d.status)" -ForegroundColor $(if($d.status -eq 'PASSED'){'Green'}else{'Yellow'});Write-Host "Drills: 6; passed: $(@($d.drills|Where-Object status -eq 'PASSED').Count); productionDataUsed: false; destructiveDownMigrationUsed: false"
if($RequirePassed -and $d.status -ne 'PASSED'){throw 'Finance staging recovery has not passed.'}
